package com.ruoyi.web.biz;
import java.util.*;
import java.math.BigDecimal;
import java.io.*;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.ss.util.CellRangeAddress;
import org.apache.poi.xssf.streaming.SXSSFWorkbook;
public final class StatisticsExcel {
 private StatisticsExcel(){}
 static final Map<String,String> LABELS=new LinkedHashMap<>();static{String[][] names={{"id","编号"},{"company_id","企业编号"},{"company_name","企业名称"},{"credit_code","信用代码"},{"user_id","账号编号"},{"employee_no","工号"},{"real_name","姓名"},{"contact_phone","电话"},{"job_title","岗位"},{"status","状态"},{"entry_date","本次入职日期"},{"leave_date","本次离职日期"},{"project_code","项目编号"},{"project_name","项目名称"},{"projectId","项目编号"},{"projectName","项目名称"},{"taskId","任务编号"},{"taskTitle","任务名称"},{"unit","单位"},{"output_date","业务日期"},{"output_value","填报产值（元）"},{"totalQuantity","目标工作量"},{"confirmedQuantity","累计已确认工作量"},{"periodConfirmedQuantity","期间已确认工作量"},{"remainingQuantity","剩余工作量"},{"percent","当前进度（%）"},{"plannedEstimate","计划估值（元，未报价留空）"},{"confirmedEstimate","确认工作量折算估值（元）"},{"periodConfirmedEstimate","期间工作量折算估值（元）"},{"pricedPlannedSubtotal","已报价部分计划估值（元）"},{"pricedTaskCount","已报价任务数"},{"unpricedTaskCount","未报价任务数"},{"unitPrice","单价（元/单位）"},{"plannedQuantity","计划工作量"},{"priceVersion","报价版本"},{"priceSnapshotTime","报价快照时间"},{"reportMonth","核对月份"},{"reportedValue","已报产值（元）"},{"confirmedValue","月度已确认产值（元）"},{"snapshotValue","上次月度核对快照（元）"},{"difference","当前已报与快照差额（元）"},{"snapshotAction","上次核对结果"},{"snapshotTime","快照时间"},{"checkStatus","月度核对状态"},{"recordCount","记录数"},{"dataset","数据集"},{"period","统计日期/月"},{"reported","已报产值（元）"},{"confirmed","其中已确认（元）"},{"work_date","工作日期"},{"quantity","工作量"},{"project_id","项目编号"},{"assignment_id","分配编号"},{"remark","备注"},{"create_time","创建时间"}};for(var n:names)LABELS.put(n[0],n[1]);String[][] summary={{"companyCount","企业数"},{"activeCompanyCount","有效企业数"},{"employeeCount","去重员工人数"},{"activeEmployeeCount","在职人数"},{"projectCount","项目数"},{"monthReportedValue","本月已报产值（元）"},{"reportedValue","期间已报产值（元）"},{"confirmedValue","其中月度已确认产值（元）"},{"submittedValue","已提交待月度确认产值（元）"},{"draftValue","草稿金额（元）"},{"returnedValue","退回金额（元）"},{"missingDays","期间应报日漏报数"},{"recordCount","记录数"},{"profileCount","档案数"},{"distinctUserCount","去重人数"},{"activeProfiles","在职档案数"},{"leftProfiles","离职档案数"},{"currentEntryInPeriod","本次入职日在期间档案数"},{"currentLeaveInPeriod","本次离职日在期间档案数"},{"completedProjects","完成或归档项目数"},{"unpricedProjects","未全额报价项目数"},{"rows","核对行数"},{"confirmedMonths","已确认企业月份数"},{"snapshotMissing","无核对快照月份数"},{"datasets","数据集数"}};for(var n:summary)LABELS.put(n[0],n[1]);}
 static void sheet(SXSSFWorkbook book,String title,List<Map<String,Object>> rows,CellStyle header,CellStyle number){Sheet sheet=book.createSheet(title);List<String> keys=new ArrayList<>();for(var row:rows)for(String key:row.keySet())if(!(row.get(key) instanceof Collection)&&!(row.get(key) instanceof Map)&&!keys.contains(key))keys.add(key);if(keys.isEmpty())keys.add("recordCount");Row first=sheet.createRow(0);for(int i=0;i<keys.size();i++){var cell=first.createCell(i);cell.setCellValue(LABELS.getOrDefault(keys.get(i),keys.get(i)));cell.setCellStyle(header);sheet.setColumnWidth(i,24*256);}int n=1;for(var row:rows){Row out=sheet.createRow(n++);for(int i=0;i<keys.size();i++){Object value=row.get(keys.get(i));if(value==null)continue;Cell cell=out.createCell(i);if(value instanceof BigDecimal decimal){if(decimal.precision()>15)cell.setCellValue(decimal.toPlainString());else{cell.setCellValue(decimal.doubleValue());cell.setCellStyle(number);}}else if(value instanceof Number num){if(String.valueOf(value).replace("-","").length()>15)cell.setCellValue(String.valueOf(value));else cell.setCellValue(num.doubleValue());}else if(value instanceof Boolean bool)cell.setCellValue(bool);else cell.setCellValue(String.valueOf(value));}}
 sheet.createFreezePane(0,1);sheet.setAutoFilter(new CellRangeAddress(0,Math.max(0,rows.size()),0,keys.size()-1));}
 public static byte[] create(String kind,Map<String,Object> data,String scope,String from,String to) throws IOException{SXSSFWorkbook book=new SXSSFWorkbook(100);try{CellStyle header=book.createCellStyle();header.setFillForegroundColor(IndexedColors.DARK_BLUE.getIndex());header.setFillPattern(FillPatternType.SOLID_FOREGROUND);Font font=book.createFont();font.setBold(true);font.setColor(IndexedColors.WHITE.getIndex());header.setFont(font);CellStyle number=book.createCellStyle();number.setDataFormat(book.createDataFormat().getFormat("0.00##"));List<Map<String,Object>> note=new ArrayList<>();note.add(Map.of("说明","范围","内容",scope));note.add(Map.of("说明","日期区间","内容",from+" ~ "+to));note.add(Map.of("说明","口径","内容","金额只统计元；项目进度为当前累计，仅已确认工作量计入；预估值非实际收入。财务按所选完整自然月核对。"));note.add(Map.of("说明","Excel精度","内容","超过15位有效数字按文本保留原值；未报价留空，不按0估算。"));sheet(book,"说明",note,header,number);
 var rows=(List<Map<String,Object>>)data.get("rows");if(data.containsKey("tables")){for(var entry:((Map<String,List<Map<String,Object>>>)data.get("tables")).entrySet())sheet(book,entry.getKey(),entry.getValue(),header,number);}else{sheet(book,"报表明细",rows,header,number);if(kind.equals("estimates")){List<Map<String,Object>> lines=new ArrayList<>();for(var row:rows)lines.addAll((List<Map<String,Object>>)row.get("quoteLines"));sheet(book,"报价与工作量明细",lines,header,number);}}
 List<Map<String,Object>> summary=new ArrayList<>();if(data.get("summary") instanceof Map<?,?> map)for(var e:map.entrySet())summary.add(Map.of("指标",LABELS.getOrDefault(String.valueOf(e.getKey()),String.valueOf(e.getKey())),"值",e.getValue()));sheet(book,"汇总指标",summary,header,number);ByteArrayOutputStream bytes=new ByteArrayOutputStream();book.write(bytes);return bytes.toByteArray();}finally{book.close();book.dispose();}}
}
